package net.officefloor.hq.app.clients;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.CollectionTable;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** A client invoices are raised for. */
@Entity
@Table(name = "client")
public class Client {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    private String email;

    /** Payment terms in days; null means the usual end of the following month. */
    private Integer termsDays;

    /** The standard percentage discount new invoices for this client start with; 0 is none. */
    @Column(name = "discount_pct")
    private BigDecimal discountPct = BigDecimal.ZERO;

    /** Whether the client is tax exempt (a charity, say): its invoices charge no tax on any line. */
    @Column(name = "tax_exempt")
    private boolean taxExempt;

    /**
     * The last issue date the client's tax exemption covers: its invoices issued after it are taxed as
     * usual; null when the exemption does not end, and always for a client that is not exempt.
     */
    @Column(name = "tax_exempt_until")
    private LocalDate taxExemptUntil;

    /** Whether the client is quoted prices that include tax: the tax is taken out of its invoice amounts. */
    @Column(name = "prices_include_tax")
    private boolean pricesIncludeTax;

    /** The currency the client is billed in: everything on its invoices is in it. */
    @Enumerated(EnumType.STRING)
    private Currency currency = Currency.USD;

    /** The percentage of the amount before tax taken off an invoice paid off early; 0 is none. */
    @Column(name = "early_pay_pct")
    private BigDecimal earlyPayPct = BigDecimal.ZERO;

    /** How many days after its issue date an invoice counts as paid off early; null when never. */
    @Column(name = "early_pay_days")
    private Integer earlyPayDays;

    /** The standard retention percentage (0 to 20) new invoices for this client start with; 0 is none. */
    @Column(name = "retention_pct")
    private BigDecimal retentionPct = BigDecimal.ZERO;

    /**
     * The percentage (0 to 100) of each invoice's amount before tax the client withholds and pays to its
     * tax office; 0 is none. It is never owed by the client.
     */
    @Column(name = "withholding_pct")
    private BigDecimal withholdingPct = BigDecimal.ZERO;

    /**
     * Days past its due date an invoice or instalment for this client is given before it is overdue,
     * and earns late interest: 0 to {@link #MAX_GRACE_DAYS}; null for their region's, else a week.
     */
    @Column(name = "grace_days")
    private Integer graceDays;

    /**
     * The client's own annual late-interest rate (0 to {@link #MAX_INTEREST_RATE} percent) charged
     * instead of the workspace's; null for the workspace's, 0 for never charged late interest.
     */
    @Column(name = "interest_rate")
    private BigDecimal interestRate;

    /**
     * The region the client is in (a state, say): its invoices are taxed at the region's rate from the
     * workspace's regional rates when one is listed; null for no region.
     */
    private String region;

    /**
     * The client's tax number, without spaces (see {@link TaxNumber}): with a valid one from its region
     * outside the workspace's home region its invoices are reverse charged; null for no number.
     */
    @Column(name = "tax_number")
    private String taxNumber;

    /**
     * The client's own minimum charge, in its currency (no conversion), charged instead of the
     * workspace's on its invoices; null for the workspace's, 0 for never charged a minimum.
     */
    @Column(name = "minimum_charge")
    private BigDecimal minimumCharge;

    /**
     * The most the client may owe, in its currency: an invoice that would take its balance over it is not
     * sent; null for no limit.
     */
    @Column(name = "credit_limit")
    private BigDecimal creditLimit;

    /**
     * The percentage (0 to 100, 0 for none) taken off every price the client's lines take from its rate card or the
     * price list (see {@link RateDiscount}).
     */
    @Column(name = "rate_discount_pct")
    private BigDecimal rateDiscountPct = BigDecimal.ZERO;

    /**
     * The client's rate card: its prices, single or tiered, per unit type (hour, day, ...), each from a date or
     * always; empty for none.
     */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "client_rate", joinColumns = @JoinColumn(name = "client_id"))
    private List<ClientRate> rates = new ArrayList<>();

    /** The highest late-interest rate a client can be given, as a percentage. */
    public static final int MAX_INTEREST_RATE = 30;

    /** The longest grace period a client can be given, in days. */
    public static final int MAX_GRACE_DAYS = 30;

    protected Client() {
    }

    public Client(String name, String email, Integer termsDays, BigDecimal discountPct, boolean taxExempt,
            boolean pricesIncludeTax, Currency currency, BigDecimal earlyPayPct, Integer earlyPayDays, BigDecimal retentionPct,
            Integer graceDays, BigDecimal interestRate, String region, String taxNumber, BigDecimal withholdingPct, BigDecimal minimumCharge,
            BigDecimal rateDiscountPct, LocalDate taxExemptUntil, BigDecimal creditLimit) {
        this.name = name;
        this.creditLimit = creditLimit;
        this.taxExemptUntil = taxExemptUntil;
        this.email = email;
        this.termsDays = termsDays;
        this.discountPct = discountPct == null ? BigDecimal.ZERO : discountPct;
        this.taxExempt = taxExempt;
        this.pricesIncludeTax = pricesIncludeTax;
        this.currency = currency == null ? Currency.USD : currency;
        this.earlyPayPct = earlyPayPct == null ? BigDecimal.ZERO : earlyPayPct;
        this.earlyPayDays = earlyPayDays;
        this.retentionPct = retentionPct == null ? BigDecimal.ZERO : retentionPct;
        this.graceDays = graceDays;
        this.interestRate = interestRate;
        this.region = region;
        this.taxNumber = taxNumber;
        this.withholdingPct = withholdingPct == null ? BigDecimal.ZERO : withholdingPct;
        this.minimumCharge = minimumCharge;
        this.rateDiscountPct = rateDiscountPct == null ? BigDecimal.ZERO : rateDiscountPct;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public Integer getTermsDays() {
        return termsDays;
    }

    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    public boolean isTaxExempt() {
        return taxExempt;
    }

    public LocalDate getTaxExemptUntil() {
        return taxExemptUntil;
    }

    public boolean isPricesIncludeTax() {
        return pricesIncludeTax;
    }

    public Currency getCurrency() {
        return currency;
    }

    public BigDecimal getEarlyPayPct() {
        return earlyPayPct;
    }

    public Integer getEarlyPayDays() {
        return earlyPayDays;
    }

    public BigDecimal getRetentionPct() {
        return retentionPct;
    }

    public BigDecimal getWithholdingPct() {
        return withholdingPct;
    }

    public BigDecimal getRateDiscountPct() {
        return rateDiscountPct;
    }

    public BigDecimal getMinimumCharge() {
        return minimumCharge;
    }

    public BigDecimal getCreditLimit() {
        return creditLimit;
    }

    public Integer getGraceDays() {
        return graceDays;
    }

    public BigDecimal getInterestRate() {
        return interestRate;
    }

    public String getRegion() {
        return region;
    }

    public String getTaxNumber() {
        return taxNumber;
    }

    public List<ClientRate> getRates() {
        return rates;
    }

    /**
     * The client's rate for the given unit type (matched ignoring case and surrounding spaces) in force on the date:
     * the latest entry from on or before it, an entry with no date before any dated one; null when none is.
     */
    public ClientRate rateFor(String unitType, LocalDate on) {
        return rates.stream().filter(r -> r.isFor(unitType) && r.inForceOn(on))
                .max(Comparator.comparing(ClientRate::getEffectiveFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .orElse(null);
    }
}
package net.officefloor.hq.app.clients;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/clients")
public class ClientController {

    public record ClientView(Long id, String name, String email, Integer termsDays, BigDecimal discountPct,
            boolean taxExempt, boolean pricesIncludeTax, Currency currency, BigDecimal earlyPayPct, Integer earlyPayDays,
            BigDecimal retentionPct, Integer graceDays, BigDecimal interestRate, String region, String taxNumber,
            List<RateView> rates, BigDecimal withholdingPct, BigDecimal minimumCharge, BigDecimal rateDiscountPct,
            LocalDate taxExemptUntil, BigDecimal creditLimit) {
        static ClientView of(Client c) {
            return new ClientView(c.getId(), c.getName(), c.getEmail(), c.getTermsDays(), c.getDiscountPct(),
                    c.isTaxExempt(), c.isPricesIncludeTax(), c.getCurrency(), c.getEarlyPayPct(), c.getEarlyPayDays(),
                    c.getRetentionPct(), c.getGraceDays(), c.getInterestRate(), c.getRegion(), c.getTaxNumber(),
                    c.getRates().stream().map(RateView::of).toList(), c.getWithholdingPct(), c.getMinimumCharge(),
                    c.getRateDiscountPct(), c.getTaxExemptUntil(), c.getCreditLimit());
        }
    }

    /**
     * A rate card entry: its unit type, the date it takes effect from (null for always), and its single unit price,
     * or else its tiers (null when it has a single price).
     */
    public record RateView(String unitType, LocalDate from, BigDecimal unitPrice, List<RateTiers.Band> tiers, BigDecimal increment, BigDecimal minUnits,
            BigDecimal taxRate) {
        static RateView of(ClientRate r) {
            RateTiers tiers = r.tiers();
            return new RateView(r.getUnitType(), r.getEffectiveFrom(), r.getUnitPrice(), tiers == null ? null : tiers.bands(), r.getIncrement(), r.getMinUnits(), r.getTaxRate());
        }
    }

    public record NewClient(
            @NotBlank(message = "Enter the client's name.")
            @Size(max = 255, message = "The name must be at most 255 characters.")
            String name,
            @NotBlank(message = "Enter the client's email address.")
            @Email(regexp = PROPER_EMAIL,
                    message = "Enter a proper email address, like name@company.com.")
            @Size(max = 255, message = "The email must be at most 255 characters.")
            String email,
            @Min(value = 1, message = "Payment terms must be from 1 to 365 days.")
            @Max(value = 365, message = "Payment terms must be from 1 to 365 days.")
            Integer termsDays,
            @DecimalMin(value = "0", message = "The standard discount must be from 0 to 100 percent.")
            @DecimalMax(value = "100", message = "The standard discount must be from 0 to 100 percent.")
            @Digits(integer = 3, fraction = 2, message = "The standard discount can have at most two decimals.")
            BigDecimal discountPct,
            /** Whether the client is tax exempt; taxed when left out. */
            Boolean taxExempt,
            /** Whether the client is quoted prices that include tax; prices exclude it when left out. */
            Boolean pricesIncludeTax,
            /** The currency the client is billed in; US dollars when left out. */
            @Pattern(regexp = "USD|EUR|GBP|JPY|CHF", message = "The currency must be USD, EUR, GBP, JPY or CHF.")
            String currency,
            @DecimalMin(value = "0", message = "The early-payment discount must be from 0 to 100 percent.")
            @DecimalMax(value = "100", message = "The early-payment discount must be from 0 to 100 percent.")
            @Digits(integer = 3, fraction = 2, message = "The early-payment discount can have at most two decimals.")
            BigDecimal earlyPayPct,
            @Min(value = 1, message = "The early-payment window must be from 1 to 365 days.")
            @Max(value = 365, message = "The early-payment window must be from 1 to 365 days.")
            Integer earlyPayDays,
            @DecimalMin(value = "0", message = "The standard retention must be from 0 to 20 percent.")
            @DecimalMax(value = "20", message = "The standard retention must be from 0 to 20 percent.")
            @Digits(integer = 2, fraction = 2, message = "The standard retention can have at most two decimals.")
            BigDecimal retentionPct,
            /** The client's grace period in days; the standard week when left out. */
            @Min(value = 0, message = "The grace period must be from 0 to 30 days.")
            @Max(value = Client.MAX_GRACE_DAYS, message = "The grace period must be from 0 to 30 days.")
            Integer graceDays,
            /** The client's own late-interest rate; the workspace's when left out. */
            @DecimalMin(value = "0", message = "The interest rate must be from 0 to 30 percent.")
            @DecimalMax(value = "30", message = "The interest rate must be from 0 to 30 percent.")
            @Digits(integer = 2, fraction = 2, message = "The interest rate can have at most two decimals.")
            BigDecimal interestRate,
            /** The region the client is in; none when left out or blank. */
            @Size(max = 64, message = "The region must be at most 64 characters.")
            String region,
            /** The client's tax number; none when left out or blank. */
            String taxNumber,
            /** The percentage of the amount before tax the client withholds for its tax office; none when left out. */
            @DecimalMin(value = "0", message = "The withholding must be from 0 to 100 percent.")
            @DecimalMax(value = "100", message = "The withholding must be from 0 to 100 percent.")
            @Digits(integer = 3, fraction = 2, message = "The withholding can have at most two decimals.")
            BigDecimal withholdingPct,
            /** The client's own minimum charge in its currency; the workspace's when left out, none when 0. */
            @DecimalMin(value = "0", message = "The minimum charge cannot be negative.")
            @Digits(integer = 17, fraction = 2, message = "The minimum charge can have at most two decimals.")
            BigDecimal minimumCharge,
            /** The percentage taken off the prices the client's lines take from the rates; none when left out. */
            @DecimalMin(value = "0", message = "The rate discount must be from 0 to 100 percent.")
            @DecimalMax(value = "100", message = "The rate discount must be from 0 to 100 percent.")
            @Digits(integer = 3, fraction = 2, message = "The rate discount can have at most two decimals.")
            BigDecimal rateDiscountPct,
            /** The last issue date the tax exemption covers; it does not end when left out. Only for an exempt client. */
            LocalDate taxExemptUntil,
            /** The most the client may owe in its currency; no limit when left out. */
            @DecimalMin(value = "0", message = "The credit limit cannot be negative.")
            @Digits(integer = 17, fraction = 2, message = "The credit limit can have at most two decimals.")
            BigDecimal creditLimit) {

        @AssertTrue(message = "Only a tax-exempt client can have an exemption end date: tick tax exempt or clear the date.")
        public boolean isTaxExemptUntilExempt() {
            return taxExemptUntil == null || Boolean.TRUE.equals(taxExempt);
        }

        @AssertTrue(message = "Enter a tax number of two letters then ten digits whose last two digits check the first eight, or leave it blank.")
        public boolean isTaxNumberValid() {
            return TaxNumber.normalize(taxNumber) == null || TaxNumber.isValid(taxNumber);
        }

        @AssertTrue(message = "Enter both the early-payment discount and its number of days, or neither.")
        public boolean isEarlyPayComplete() {
            return (earlyPayPct == null || earlyPayPct.signum() == 0) == (earlyPayDays == null);
        }
    }

    /**
     * A proper email address: a mailbox, an @, and a domain with at least one dot whose parts are
     * not empty — so name@company.com, but not name@company (a typo) or name.company.com.
     */
    static final String PROPER_EMAIL = "\\s*[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+\\s*";

    private final ClientService clients;

    public ClientController(ClientService clients) {
        this.clients = clients;
    }

    @GetMapping
    public List<ClientView> list() {
        return clients.list().stream().map(ClientView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ClientView add(@Valid @RequestBody NewClient body) {
        return ClientView.of(clients.add(body.name(), body.email(), body.termsDays(), body.discountPct(),
                Boolean.TRUE.equals(body.taxExempt()), Boolean.TRUE.equals(body.pricesIncludeTax()), Currency.orUsd(body.currency()), body.earlyPayPct(), body.earlyPayDays(),
                body.retentionPct(), body.graceDays(), body.interestRate(), body.region(), body.taxNumber(), body.withholdingPct(), body.minimumCharge(),
                body.rateDiscountPct(), body.taxExemptUntil(), body.creditLimit()));
    }
}
package net.officefloor.hq.app.clients;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Lists and adds clients. Clients are listed A to Z by name, ignoring capitals. No two clients share
 * an email address, ignoring capitals.
 */
@Service
public class ClientService {

    static final Comparator<Client> BY_NAME = Comparator
            .comparing(Client::getName, String.CASE_INSENSITIVE_ORDER)
            .thenComparing(Client::getName)
            .thenComparing(Client::getId);

    private final ClientRepository clients;

    public ClientService(ClientRepository clients) {
        this.clients = clients;
    }

    @Transactional(readOnly = true)
    public List<Client> list() {
        return clients.findAll().stream().sorted(BY_NAME).toList();
    }

    @Transactional
    public Client add(String name, String email, Integer termsDays, BigDecimal discountPct, boolean taxExempt,
            boolean pricesIncludeTax, Currency currency, BigDecimal earlyPayPct, Integer earlyPayDays, BigDecimal retentionPct, Integer graceDays,
            BigDecimal interestRate, String region, String taxNumber, BigDecimal withholdingPct, BigDecimal minimumCharge,
            BigDecimal rateDiscountPct, LocalDate taxExemptUntil, BigDecimal creditLimit) {
        String address = email.trim();
        if (clients.existsByEmailIgnoreCase(address)) {
            throw new ClientRejectedException("Another client already has the email " + address + ".");
        }
        return clients.save(new Client(name.trim(), address, termsDays, discountPct, taxExempt, pricesIncludeTax, currency, earlyPayPct, earlyPayDays, retentionPct, graceDays, interestRate,
                region == null || region.isBlank() ? null : region.trim(), TaxNumber.normalize(taxNumber), withholdingPct, minimumCharge, rateDiscountPct, taxExemptUntil, creditLimit));
    }
