136	    private void applyCredit(Invoice invoice) {
137	        BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
138	        BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
139	        LocalDate now = today.date();
140	        boolean used = false;
141	        Map<String, Long> drafts = draftsByReference(invoice.getClientId());
142	        List<Payment> usable = new ArrayList<>();
143	        List<Payment> others = new ArrayList<>();
144	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
145	            Long heldFor = heldFor(payment, drafts);
