149	                others.add(payment);
150	            }
151	        }
152	        usable.addAll(others);
153	        BigDecimal early = BigDecimal.ZERO;
154	        BigDecimal settle = invoice.settleAmount(paidSoFar, taxRate.percent(), now);
155	        if (settle != null && usable.stream().map(Payment::credit).filter(c -> c.signum() > 0)
156	                .reduce(BigDecimal.ZERO, BigDecimal::add).compareTo(settle) >= 0) {
157	            early = invoice.earlyDiscount(taxRate.percent());
158	            invoice.takeEarlyDiscount(early);
159	            due = settle;
